bits = {'R': 1, 'W': 2, 'X': 4}
rights = {}
for _ in range(int(input())):
    name, *allowed = input().split()
    mask = 0
    for letter in allowed:
        mask |= bits[letter]
    rights[name] = mask
operation = {'read': 1, 'write': 2, 'execute': 4}
for _ in range(int(input())):
    action, name = input().split()
    print('OK' if rights[name] & operation[action] else 'Access denied')
